import{_ as c,o,c as a,a2 as r}from"./chunks/framework.ClgMjOt7.js";const m=JSON.parse('{"title":"プライバシー & セキュリティ保護","description":"アプリロック、生体認証、電卓偽装モード、タスク隠蔽、スクリーンショット防止","frontmatter":{"title":"プライバシー & セキュリティ保護","description":"アプリロック、生体認証、電卓偽装モード、タスク隠蔽、スクリーンショット防止"},"headers":[],"relativePath":"features/privacy-security.md","filePath":"features/privacy-security.md","lastUpdated":1786166106000}'),i={name:"features/privacy-security.md"};function d(l,e,t,n,s,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="プライバシー-セキュリティ保護" tabindex="-1">プライバシー &amp; セキュリティ保護 <a class="header-anchor" href="#プライバシー-セキュリティ保護" aria-label="Permalink to &quot;プライバシー &amp; セキュリティ保護&quot;">​</a></h1><p>アプリの起動保護、偽装表示、および画面情報の保護仕様です。</p><hr><h2 id="アプリロック-生体認証-applockscreen-applocksetupscreen" tabindex="-1">アプリロック &amp; 生体認証 (<code>AppLockScreen</code> / <code>AppLockSetupScreen</code>) <a class="header-anchor" href="#アプリロック-生体認証-applockscreen-applocksetupscreen" aria-label="Permalink to &quot;アプリロック &amp; 生体認証 (`AppLockScreen` / `AppLockSetupScreen`)&quot;">​</a></h2><ul><li><strong>PIN ロック</strong>: 4〜8 桁の暗証番号による保護 (<code>appLockEnabled</code>)。</li><li><strong>生体認証</strong>: Android 標準の BiometricPrompt を使用した指紋/顔認証 (<code>biometricEnabled</code>)。</li><li><strong>自動ロックタイマー (<code>privacyModeAutoLockTiming</code>)</strong>: <ul><li><code>immediate</code> (即時ロック)</li><li><code>30s</code> / <code>1m</code> / <code>5m</code> / <code>10m</code></li><li><code>disabled</code> (自動ロックなし)</li></ul></li></ul><hr><h2 id="電卓偽装モード-calculatorscreen-calculatorengine" tabindex="-1">電卓偽装モード (<code>CalculatorScreen</code> / <code>CalculatorEngine</code>) <a class="header-anchor" href="#電卓偽装モード-calculatorscreen-calculatorengine" aria-label="Permalink to &quot;電卓偽装モード (`CalculatorScreen` / `CalculatorEngine`)&quot;">​</a></h2><p>アプリの起動画面を電卓UIへ偽装し、特定操作でのみ本機能へアクセスできるようにするセキュリティ設定です。</p><ul><li><strong>四則演算パーサー (<code>CalculatorEngine</code>)</strong>: <ul><li>再帰降下パーサーを実装し、数値、演算子 (<code>+</code>, <code>-</code>, <code>×</code>, <code>÷</code>)、小数点含む式を実際に評価。</li></ul></li><li><strong>解錠パターン</strong>: <ul><li>設定した PIN コードを電卓に入力して <code>=</code> ボタンをタップすることでロック解除。</li><li>右上隅の指定エリアを連続タップすることで緊急解錠ダイアログ（レスキュー入力）を呼び出し可能。</li></ul></li><li><strong>アプリアイコン・名称変更</strong>: <ul><li><code>dummyAppName</code>: ホーム画面上の表示名を「電卓」に変更。</li><li><code>dummyIconVariant</code>: アプリアイコンを電卓アイコン（<code>ic_launcher_dummy</code>）へ動的コンポーネント切り替え。</li></ul></li></ul><hr><h2 id="画面・キャプション保護-privacymodesettingsscreen" tabindex="-1">画面・キャプション保護 (<code>PrivacyModeSettingsScreen</code>) <a class="header-anchor" href="#画面・キャプション保護-privacymodesettingsscreen" aria-label="Permalink to &quot;画面・キャプション保護 (`PrivacyModeSettingsScreen`)&quot;">​</a></h2><ul><li><code>secureWindow</code> (<code>FLAG_SECURE</code>): 有効化時、Android システムのキャプション機能を遮断し、画面のスクリーンショット撮影および録画を禁止。</li><li><code>hideRecents</code>: Android の「最近使ったアプリ」（タスクスイッチャー）一覧で、アプリのプレビュー画面をマスク表示。</li></ul>',12)])])}const h=c(i,[["render",d]]);export{m as __pageData,h as default};
